{
  "$defs": {
    "FruitNameInput": {
      "description": "Input model for fruit lookup requests.\n\nAttributes:\n    name (str): The name of the fruit to retrieve data for.",
      "properties": {
        "name": {
          "description": "Name of the fruit to retrieve data for",
          "title": "Name",
          "type": "string"
        }
      },
      "required": [
        "name"
      ],
      "title": "FruitNameInput",
      "type": "object"
    }
  },
  "description": "Fetch detailed information about a specific fruit from the Fruityvice API.\n\nThe information returned typically includes nutritional data (calories, fat, sugar, etc.),\nfamily, genus, and other taxonomic details.\n\nArgs:\n    input (FruitNameInput): Object containing the name of the fruit to look up.\n\nReturns:\n    Dict[str, Any]: A dictionary containing the fruit's details and nutritional information.\n    If the fruit is not found, returns a dictionary with an error message.\n\nRaises:\n    requests.HTTPError: If the API request fails for reasons other than a 404.",
  "properties": {
    "input": {
      "$ref": "#/$defs/FruitNameInput"
    }
  },
  "required": [
    "input"
  ],
  "title": "get_fruit_info",
  "type": "object"
}
```

